commands:
make check 2>&1 | tail -n 4; make lint 2>&1 | tail -n 1; echo "--- long lines"; awk 'length($0) > 60 { print FILENAME":"NR": "length($0) }' hourglass/timesheet.py tests/test_timesheet.py; echo "--- double blanks"; for f in hourglass/timesheet.py tests/test_timesheet.py; do awk -v file="$f" '/^$/ { blanks++; if (blanks == 2) print file": double blank at "NR } !/^$/ { blanks = 0 }' "$f"; done; echo "--- function sizes (signature through last line)"; python3 - <<'EOF'
import ast
for path in ("hourglass/timesheet.py", "tests/test_timesheet.py"):
    tree = ast.parse(open(path).read())
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef,)):
            print(path, node.name, node.end_lineno - node.lineno + 1)
EOF
echo "--- python files without owner line"; for f in hourglass/timesheet.py tests/test_timesheet.py; do head -n 1 "$f"; done

